-- PRIVÉ · S12 V3.1 · Perfiles enriquecidos en Supabase
-- Ejecutar UNA sola vez en Supabase SQL Editor como postgres.
-- Objetivo: Supabase pasa a ser la fuente única del catálogo público, incluido el perfil olfativo.
-- Seguridad: NO expone perfume_keys, source_url, provenance ni campos administrativos.

reset role;

create table if not exists public.perfume_profiles (
  perfume_id uuid primary key references public.perfumes(id) on delete cascade,
  profile_data jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);

alter table public.perfume_profiles enable row level security;

-- Nadie navega directamente esta tabla desde el catálogo público.
revoke all on table public.perfume_profiles from anon;
revoke all on table public.perfume_profiles from authenticated;

-- Normalización interna para empatar el catálogo histórico por diseñador + nombre.
create or replace function public.prive_catalog_norm(value text)
returns text
language sql
immutable
strict
set search_path = public
as $$
  select lower(
    regexp_replace(
      translate(trim(value),
        'ÁÉÍÓÚÜÑÀÈÌÒÙÂÊÎÔÛÄËÏÖÜÇáéíóúüñàèìòùâêîôûäëïöüç',
        'AEIOUUNAEIOUAEIOUAEIOUCAEIOUUNAEIOUAEIOUAEIOUC'
      ),
      '[^a-zA-Z0-9]+', ' ', 'g'
    )
  );
$$;

