  ('XERJOFF', 'ACCENTO', '{"family":"Chipre floral","topNotes":["Piña","Jacinto"],"heartNotes":["Iris","Jazmín","Pimienta rosa"],"baseNotes":["Almizcle","Vetiver","Pachulí","Ámbar","Vainilla"],"accords":["Floral","Amaderado","Atalcado","Afrutado","Almizclado","Avainillado"],"styleTags":["Frutal","Almizclado y elegante"],"intensity":"Intenso","occasions":["Día","Noche","Diario","Oficina","Cita"],"contexts":["Día","Noche","Diario","Oficina","Cita","Casual","Profesional","Social"],"climates":["Templado","Calor","Frío"],"seasons":["Primavera","Otoño","Verano"],"dayParts":["Mañana","Tarde","Noche"],"sensoryProfile":{"freshness":0,"sweetness":5,"warmth":4,"woodiness":5,"spiciness":2,"floral":5,"citrus":0,"fruitiness":4,"aquatic":0,"powdery":5,"smoky":0,"leathery":0},"ageTrend":{"min":20,"max":58,"confidence":"low","framing":"tendency","isRestrictive":false,"guidance":"Tendencia orientativa: suele conectar especialmente con personas de 20 a 58 años por su estilo frutal, almizclado y elegante. No es una regla ni limita su uso: si te atraen sus notas y la imagen que proyecta, puede funcionar muy bien a cualquier edad. Si buscas una impresión más juvenil o más clásica, el Asesor PRIVÉ puede sugerirte alternativas cercanas."},"description":"Una fragancia de perfil floral, amaderado, atalcado, con una salida de piña, jacinto que evoluciona hacia un fondo de almizcle, vetiver, pachulí. Su carácter frutal, almizclado y elegante ayuda al Asesor PRIVÉ a ubicarla por gusto, ocasión y clima sin convertir la edad en una regla.","advisorSummary":"Perfil frutal, almizclado y elegante. Afinidad orientativa: 20 a 58 años; sus notas pueden funcionar a cualquier edad según tus gustos y la imagen que deseas proyectar."}'::jsonb),
