), matched as (
  -- DISTINCT ON evita que una entrada histórica duplicada intente hacer UPSERT
  -- dos veces sobre el mismo perfume_id dentro del mismo comando.
  select distinct on (p.id) p.id as perfume_id, s.profile_data
  from seed s
  join public.perfumes p
    on public.prive_catalog_norm(p.designer) = public.prive_catalog_norm(s.designer)
   and public.prive_catalog_norm(p.name) = public.prive_catalog_norm(s.name)
  order by p.id
)
insert into public.perfume_profiles (perfume_id, profile_data, updated_at)
select perfume_id, profile_data, now()
from matched
on conflict (perfume_id) do update
set profile_data = excluded.profile_data,
    updated_at = now();

-- Los perfiles migrados pasan a estado enriched.
update public.perfumes p
set profile_status = 'enriched'
where exists (
  select 1 from public.perfume_profiles pp where pp.perfume_id = p.id
);

-- RPC pública segura: devuelve identidad operativa + perfil público, nunca secretos.
-- PostgreSQL no permite cambiar el RETURNS TABLE con CREATE OR REPLACE; se recrea explícitamente.
drop function if exists public.get_public_catalog();

create function public.get_public_catalog()
returns table (
  id uuid,
  name text,
  designer text,
  category text,
  image_url text,
  availability_status text,
  profile_status text,
  profile_data jsonb
)
language sql
stable
security definer
set search_path = public
as $$
  select
    p.id,
    p.name,
    p.designer,
    p.category::text,
    p.image_url,
    p.availability_status::text,
    p.profile_status::text,
    coalesce(pp.profile_data, '{}'::jsonb)
  from public.perfumes p
  left join public.perfume_profiles pp on pp.perfume_id = p.id
  where p.active = true
  order by p.designer asc, p.name asc;
$$;

revoke all on function public.get_public_catalog() from public;
grant execute on function public.get_public_catalog() to anon, authenticated;

comment on table public.perfume_profiles is
'Perfiles públicos enriquecidos PRIVÉ. Sin claves privadas ni URLs fuente administrativas.';
comment on function public.get_public_catalog() is
'Catálogo público PRIVÉ desde Supabase: identidad, disponibilidad y perfil enriquecido seguro.';

-- VALIDACIÓN 1: muestra cuántos perfiles históricos encontraron perfume operativo.
select
  (select count(*) from public.perfume_profiles) as perfiles_en_supabase,
  (select count(*) from public.perfumes where active = true) as perfumes_activos;

-- VALIDACIÓN 2: debe devolver ocho columnas; profile_data tendrá datos para enriquecidos y {} para básicos.
select id, name, designer, category, image_url, availability_status, profile_status, profile_data
from public.get_public_catalog()
limit 5;
